css:
.loader {
  display: flex;
  justify-content: center;
  align-items: center;
}
.container {
  overflow: visible;
}
.track,
.car {
  fill: none;
  stroke-width: 2.5;
}
.track {
  stroke: #d0d0d0;
}
.car {
  stroke: #4f8cff;
  stroke-linecap: round;
  stroke-dasharray: 25 75;
  animation: borderMove 2s linear infinite;
}

.baseline {
  stroke: #ccc;
  stroke-width: 1.5;
  stroke-dasharray: 2 2;
}

.letters text {
  font-family: "JetBrains Mono", "SF Mono", Menlo, monospace;
  font-size: 9px;
  font-weight: 700;
  fill: #4f8cff;
  animation: fall 1.6s cubic-bezier(0.5, 0, 1, 0.5) infinite;
}
.letters text:nth-child(1) {
  animation-delay: 0s;
}
.letters text:nth-child(2) {
  animation-delay: 0.35s;
  fill: #ff6b6b;
}
.letters text:nth-child(3) {
  animation-delay: 0.7s;
  fill: #ffd166;
}
.letters text:nth-child(4) {
  animation-delay: 1.05s;
  fill: #6bffb0;
}

@keyframes borderMove {
  from {
    stroke-dashoffset: 100;
  }
  to {
    stroke-dashoffset: 0;
  }
}
@keyframes fall {
  0% {
    transform: translateY(0);
    opacity: 0;
  }
  10% {
    opacity: 1;
  }
  75% {
    transform: translateY(20px);
    opacity: 1;
  }
  85%,
  100% {
    transform: translateY(20px);
    opacity: 0;
  }
}
